<?php ob_start(); $editing = $editing ?? false; ?><section class="section narrow"><p class="eyebrow">Administration</p><h1><?= $editing ? 'Modifier la salle' : 'Ajouter une salle' ?></h1><form method="post" action="<?= $editing ? '/salles/' . $salle->id . '/edit' : '/salles' ?>"><label>Nom<input name="nom" value="<?= htmlspecialchars($salle->nom ?? '') ?>" required><?= !empty($errors['nom']) ? '<small>'.htmlspecialchars($errors['nom']).'</small>' : '' ?></label><label>Batiment<input name="batiment" value="<?= htmlspecialchars($salle->batiment ?? '') ?>" required><?= !empty($errors['batiment']) ? '<small>'.htmlspecialchars($errors['batiment']).'</small>' : '' ?></label><label>Capacite<input type="number" name="capacite" min="1" max="1000" value="<?= htmlspecialchars((string) ($salle->capacite ?? '')) ?>" required><?= !empty($errors['capacite']) ? '<small>'.htmlspecialchars($errors['capacite']).'</small>' : '' ?></label><label>Type<select name="type" required><option value="">Choisir</option><?php foreach (['cours','informatique','laboratoire','amphitheatre','reunion'] as $type): ?><option <?= ($salle->type ?? '') === $type ? 'selected' : '' ?>><?= $type ?></option><?php endforeach; ?></select><?= !empty($errors['type']) ? '<small>'.htmlspecialchars($errors['type']).'</small>' : '' ?></label><button class="button" type="submit"><?= $editing ? 'Enregistrer les modifications' : 'Enregistrer' ?></button></form></section><?php $content = ob_get_clean(); require dirname(__DIR__) . '/layout/base.php';